from pathlib import Path
import json, re

p = Path('index.html')
src = p.read_text(encoding='utf-8')

THEMES = ['confidence', 'work', 'future', 'calm', 'love']
by_theme = {t: [] for t in THEMES}

# Keep good existing short diary-derived phrases first.
m = re.search(r"    const AFFIRMATIONS = \[(.*?)\n    \]\.map\(\(x, i\) => \(\{ id: `[^`]+`, theme: x\[0\], text: x\[1\] \}\)\);", src, re.S)
if not m:
    raise SystemExit('AFFIRMATIONS block not found')

for line in m.group(1).splitlines():
    line = line.strip().rstrip(',')
    mm = re.match(r'^\[("(?:[^"\\]|\\.)*"),("(?:[^"\\]|\\.)*")\]$', line)
    if not mm:
        continue
    theme, text = json.loads(mm.group(1)), json.loads(mm.group(2))
    if theme in by_theme:
        by_theme[theme].append(text.strip())

