banned = ['Мне выгодно думать', 'Игорь', 'Яна', 'Катя', 'Алёна', 'Алена']
selected = []
seen = set()

for theme in THEMES:
    count = 0
    for text in by_theme[theme]:
        text = re.sub(r'\s+', ' ', text).strip()
        if len(text) > 75:
            continue
        if any(x.lower() in text.lower() for x in banned):
            continue
        key = text.lower()
        if key in seen:
            continue
        selected.append((theme, text))
        seen.add(key)
        count += 1
        if count == 100:
            break
    if count != 100:
        raise SystemExit(f'Only {count} valid phrases for {theme}')

assert len(selected) == 500
assert len({t.lower() for _, t in selected}) == 500
assert max(len(t) for _, t in selected) <= 75
assert all(not any(x.lower() in t.lower() for x in banned) for _, t in selected)

rows = ['      [' + json.dumps(theme, ensure_ascii=False) + ',' + json.dumps(text, ensure_ascii=False) + ']' for theme, text in selected]
block = '    const AFFIRMATIONS = [\n' + ',\n'.join(rows) + '\n    ].map((x, i) => ({ id: `q${i+1}`, theme: x[0], text: x[1] }));'
pattern = r"    const AFFIRMATIONS = \[.*?\n    \]\.map\(\(x, i\) => \(\{ id: `[^`]+`, theme: x\[0\], text: x\[1\] \}\)\);"
src, n = re.subn(pattern, lambda _: block, src, count=1, flags=re.S)
if n != 1:
    raise SystemExit('Could not replace AFFIRMATIONS')
src = re.sub(r"affirm_[A-Za-z0-9_:.-]*saved[A-Za-z0-9_:.-]*", 'affirm_500_short_saved_v1', src)
p.write_text(src, encoding='utf-8')
print('Installed 500 unique affirmations; max length:', max(len(t) for _, t in selected))
